const e=JSON.parse(`[{"id":"upsc-2016-prelims-csat-a-041","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":41,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most logical corollary to the above passage ?","options":{"a":"Launching more welfare schemes and allocating more finances for the current schemes r are urgently needed","b":"Efforts should be made to push up economic growth by other means and provide licences to the poor","c":"Greater transparency in the functioning of the government and promoting the financial inclusion are needed at present","d":"We should concentrate more on developing manufacturing sector than service sector"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"By killing transparency and competition, crony capitalism is harmful to free enterprise, opportunity and economic growth. Crony capitalism, where rich and the influential are alleged to have received land and natural resources and various licences in return for payoffs to venal politicians, is now a major issue to be tackled. One of the greatest dangers to growth of developing economies like India is the middle-income trap where crony capitalism creates oligarchies that slow down the growth."},{"type":"paragraph","text":"Which among the following is the most logical corollary to the above passage ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Crony capitalism blocks transparency, competition and fair opportunity. Increasing governmental transparency and wider financial access follows from removing those barriers; additional schemes alone do not address them.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-042","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":42,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is the most logical and rational inference that can be made from the above passage?","options":{"a":"It is difficult to pursue climate adaptation in the developing countries","b":"Improving food security is a far more complex issue than climate adaptation","c":"Every developmental activity is directly or indirectly linked to climate adaptation","d":"Climate adaptation should be examined in tandem with other economic development options"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Climate adaptation may be rendered ineffective if policies are not designed in the context of other development concerns. For instance, a comprehensive strategy that seeks to improve food security in the context of climate change may include a set of coordinated measures related to agricultural extension, crop diversification, integrated water and pest management and agricultural information services. Some of these measures may have to do with climate changes and others with economic development."},{"type":"paragraph","text":"What is the most logical and rational inference that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage warns against treating adaptation separately from development and gives coordinated food-security measures. Climate adaptation should be considered alongside other economic development options.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-043","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":43,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most critical inference that can be made from the above passage ?","options":{"a":"biodiversity sustains the ability of nature to recycle water","b":"We cannot get potable water without the existence of living organisms","c":"Plants, animals and microorganisms continuously interact among themselves","d":"Living organisms could not have come into existence without hydrological cycle"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Understanding of the role of biodiversity in the hydrological cycle enables better policy-making. The term biodiversity refers to the variety of plants, animals, microorganisms, and the ecosystems in which they occur. Water and biodiversity are interdependent. In reality, the hydrological cycle decides how biodiversity functions. In turn, vegetation and soil drive the movement of water. Every glass of water we drink has, at least in part, passed through fish, trees, bacteria, soil and other organisms. Passing through these ecosystems, it is cleansed and made fit for consumption. The supply of water is a critical service that the environment provides."},{"type":"paragraph","text":"Which among the following is the most critical inference that can be made from the above passage ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Vegetation, soil and organisms move and clean water as it cycles through ecosystems. Biodiversity therefore supports nature’s capacity to recycle water.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-044","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":44,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the message that is essentially implied in the above passage?","options":{"a":"Need for more automation and more products of bank","b":"Need for a radical restructuring of our entire public finance system","c":"Need to integrate banking and non-banking institutions","d":"Need to promote financial inclusion"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"In the last decade, the banking sector has been restructured with a high degree of automation and products that mainly serve middle-class and upper middle-class society. Today there is need for a new agenda for the banking and non-banking financial services that does not exclude the common man"},{"type":"paragraph","text":"Which one of the following is the message that is essentially implied in the above passage?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage contrasts banking that serves comfortable groups with an agenda that includes the common person. Promoting financial inclusion is the essential message.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-045","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":45,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, consider the following statements:\\n\\n1. Urban sanitation problems can be fully solved by the abolition of manual scavenging only\\n\\n2. There is a need to promote greater awareness on safe sanitation practices in urban areas.\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Safe and sustainable sanitation in slums has immeasurable benefits to women and girls in terms of their health, safety, privacy and dignity. However, women do not feature in most of the schemes and policies on urban sanitation. The fact that even now the manual scavenging exists, only goes to show that not enough has been done to promote pour-flush toilets and discontinue the use of dry latrines. A more sustained and rigorous campaign needs to be launched towards the right to sanitation on a very large scale. This should primarily focus on the abolition of manual scavenging."},{"type":"paragraph","text":"With reference to the above passage, consider the following statements:"},{"type":"paragraph","text":"1. Urban sanitation problems can be fully solved by the abolition of manual scavenging only"},{"type":"paragraph","text":"2. There is a need to promote greater awareness on safe sanitation practices in urban areas.\\nWhich of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage calls for a broad, sustained sanitation campaign and better awareness, not merely abolishing manual scavenging. Statement 2 is supported; statement 1’s “fully solved” is too strong.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-046","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":46,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most logical and rational inference that can be made from the above passage ?","options":{"a":"Nature has created a great diversity in human society","b":"Any given human society is always short of its wants","c":"Social life is a specific characteristic of man","d":"Diverse natural wants forced man towards social system"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"To understand the nature and quantity of Government proper for man, it is necessary to attend to his character. As nature created him for social life, she fitted him for the station she intended. In all cases she made his natural wants greater than his individual powers. No one man is capable, without the aid of society, of supplying his own wants; and those wants, acting upon every individual, impel the whole of them into society."},{"type":"paragraph","text":"Which among the following is the most logical and rational inference that can be made from the above passage ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Individuals cannot satisfy all their natural wants alone. These wants draw them into cooperation and society. Diverse wants therefore push humans towards a social system.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-047","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":47,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The statement refers to:","options":{"a":"the antithesis of Politics and Economics","b":"the interrelationship of Politics and Economics","c":"the predominance of Economics over Politics","d":"the predominance of Politics over Economics"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"The nature of the legal imperatives in any given state corresponds to the effective demands that state encounters, and that these, in their turn, depend, in a general way, upon the manner in which economic power is distributed in the society which the state controls."},{"type":"paragraph","text":"The statement refers to:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The statement connects legal and political demands with the distribution of economic power. It demonstrates the interrelationship of politics and economics.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-048","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":48,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most logical and rational inference that can be made from the above passage?","options":{"a":"Organic farming should immediately replace mechanised and chemical dependant agricultural practices all over the world","b":"It is imperative for us to modify our land use practices in order to mitigate climate change.","c":"There are no technological solutions to the problem of greenhouse gas emissions","d":"Tropical areas are the chief sites of carbon sequestration"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"About 15 per cent of global greenhouse gas emissions come from agricultural practices. This includes nitrous oxide from fertilizers; methane from livestock, rice production, and manure storage; and carbon dioxide (CO₂) from burning biomass, but this excludes CO₂ emissions from soil management practices, savannah burning and deforestation. Forestry, land use, and land-use change account for another 17 per cent of greenhouse gas emissions each year, three quarters of which come from tropical deforestation. The remainder is largely from draining and burning tropical peatland. About the same amount of carbon is stored in the world’s peatlands as is stored in the Amazon rainforest."},{"type":"paragraph","text":"Which among the following is the most logical and rational inference that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Agriculture, forestry and land-use change are linked to substantial greenhouse emissions. Changing land-use practices is therefore necessary for mitigation; the passage does not mandate immediate universal organic farming.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-049","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":49,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A person climbs a hill in a straight path from point 'O' on the ground in the direction of north-east and reaches a point 'A' after travelling a distance of 5 km. Then, from the point 'A' he moves to point 'B' in the direction of north-west. Let the distance AB be 12 km. Now, how far is the person away from the starting point 'O'?","options":{"a":"7 km","b":"13 km","c":"17 km","d":"11 km"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A person climbs a hill in a straight path from point 'O' on the ground in the direction of north-east and reaches a point 'A' after travelling a distance of 5 km. Then, from the point 'A' he moves to point 'B' in the direction of north-west. Let the distance AB be 12 km. Now, how far is the person away from the starting point 'O'?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"North-east and north-west directions are perpendicular. The 5 km and 12 km legs form a right triangle, so distance from the start is √(5²+12²)=13 km.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-050","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":50,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"An agricultural field is in the form of a rectangle having length X₁ meters and breadth X₂ meters (X₁ and X₂ are variable). If X₁ + X₂ = 40 meters, then the area of the agricultural field will not exceed which one of the following values?","options":{"a":"400 sq m","b":"300 sq m","c":"200 sq m","d":"80 sq m"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"An agricultural field is in the form of a rectangle having length X₁ meters and breadth X₂ meters (X₁ and X₂ are variable). If X₁ + X₂ = 40 meters, then the area of the agricultural field will not exceed which one of the following values?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"For a fixed sum X1+X2=40, the product is maximised when both are 20. Maximum area = 20×20 = 400 m².","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-051","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":51,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"The sum of the ages of 5 members comprising a family, 3 years ago was 80 years. The average age of the family today is the same as it was 3 years ago, because of an addition of a baby during the intervening period. How old is the baby ?","options":{"a":"6 months","b":"1 year","c":"2 years","d":"2 years and 6 months"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"The sum of the ages of 5 members comprising a family, 3 years ago was 80 years. The average age of the family today is the same as it was 3 years ago, because of an addition of a baby during the intervening period. How old is the baby ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The earlier average is 80/5=16 years. Today the original five total 95 years, and six members at the same average total 96. The baby is therefore 1 year old.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-052","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":52,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"The total emoluments of two persons are the same, but one gets allowances to the extent of 65% of his basic pay and the other gets allowances to the extent of 80% of his basic pay. The ratio of the basic pay of the former to the basic pay of the latter is:","options":{"a":"16 : 13","b":"5 : 4","c":"7 : 5","d":"12 : 11"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"The total emoluments of two persons are the same, but one gets allowances to the extent of 65% of his basic pay and the other gets allowances to the extent of 80% of his basic pay. The ratio of the basic pay of the former to the basic pay of the latter is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Equal total pay gives 1.65a=1.80b. Thus a:b = 1.80:1.65 = 12:11.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-053","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":53,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"A person is standing on the first step from the bottom of a ladder. If he has to climb 4 more steps to reach exactly the middle step, how many steps does the ladder have?","options":{"a":"8","b":"9","c":"10","d":"11"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A person is standing on the first step from the bottom of a ladder. If he has to climb 4 more steps to reach exactly the middle step, how many steps does the ladder have?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"After four more steps the person reaches step 5, the middle. There are four steps below and four above it, so the ladder has 9 steps.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-054","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":54,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"What is C's surname ?","options":{"a":"Ribeiro","b":"Kumar","c":"Singh","d":"Cannot be determined"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the given information and answer the three items that follow.\\n\\nWhen three friends A, B and C met, it was found that each of them wore an outer garment of a different colour. In random order, the garments are: jacket, sweater and tie; and the colours are: blue, white and black. Their surnames in random order are: Ribeiro, Kumar and Singh.\\n\\nFurther, we know that :\\n\\n1. neither B nor Ribeiro wore a white sweater\\n\\n2. C wore a tie\\n\\n3. Singh's garment was not white\\n\\n4. Kumar does not wear a jacket\\n\\n5. Ribeiro does not like to wear the black colour\\n\\n6. Each of the friends wore only one outer garment of only one colour"},{"type":"paragraph","text":"What is C's surname ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The white sweater belongs to A, since neither B nor Ribeiro wears it and C wears a tie. The constraints then give A Kumar, B Singh and C Ribeiro. Thus C’s surname is Ribeiro.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-055","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":55,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"What is the colour of the tie ?","options":{"a":"Black","b":"Blue","c":"White","d":"Cannot be determined"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the given information and answer the three items that follow.\\n\\nWhen three friends A, B and C met, it was found that each of them wore an outer garment of a different colour. In random order, the garments are: jacket, sweater and tie; and the colours are: blue, white and black. Their surnames in random order are: Ribeiro, Kumar and Singh.\\n\\nFurther, we know that :\\n\\n1. neither B nor Ribeiro wore a white sweater\\n\\n2. C wore a tie\\n\\n3. Singh's garment was not white\\n\\n4. Kumar does not wear a jacket\\n\\n5. Ribeiro does not like to wear the black colour\\n\\n6. Each of the friends wore only one outer garment of only one colour"},{"type":"paragraph","text":"What is the colour of the tie ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"C is Ribeiro and wears the tie. Ribeiro does not wear black and the white sweater belongs to A, leaving blue for the tie.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-056","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":56,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Who wore the sweater ?","options":{"a":"A","b":"B","c":"C","d":"Cannot be determined"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the given information and answer the three items that follow.\\n\\nWhen three friends A, B and C met, it was found that each of them wore an outer garment of a different colour. In random order, the garments are: jacket, sweater and tie; and the colours are: blue, white and black. Their surnames in random order are: Ribeiro, Kumar and Singh.\\n\\nFurther, we know that :\\n\\n1. neither B nor Ribeiro wore a white sweater\\n\\n2. C wore a tie\\n\\n3. Singh's garment was not white\\n\\n4. Kumar does not wear a jacket\\n\\n5. Ribeiro does not like to wear the black colour\\n\\n6. Each of the friends wore only one outer garment of only one colour"},{"type":"paragraph","text":"Who wore the sweater ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"C wears the tie, and B cannot wear the white sweater. The sweater belongs to A; the remaining jacket belongs to B.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-057","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":57,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"AB is a vertical trunk of a huge tree with A being the point where the base of the trunk touches the ground. Due to a cyclone, the trunk has been broken at C which is at a height of 12 meters, broken part is partially attached to the vertical portion of the trunk at C. If the end of the broken part B touches the ground at D which is at a distance of 5 meters from A, then the original height of the trunk is:","options":{"a":"20 m","b":"25 m","c":"30 m","d":"35 m"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"AB is a vertical trunk of a huge tree with A being the point where the base of the trunk touches the ground. Due to a cyclone, the trunk has been broken at C which is at a height of 12 meters, broken part is partially attached to the vertical portion of the trunk at C. If the end of the broken part B touches the ground at D which is at a distance of 5 meters from A, then the original height of the trunk is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The broken part forms the hypotenuse of a right triangle with legs 12 m and 5 m, so its length is 13 m. Original height = 12+13 = 25 m.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-058","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":58,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A person walks 12 km due north, then 15 km due east, after that 19 km due west and then 15 km due south. How far is he from the starting point?","options":{"a":"5 km","b":"9 km","c":"37 km","d":"61 km"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A person walks 12 km due north, then 15 km due east, after that 19 km due west and then 15 km due south. How far is he from the starting point?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Net displacement is 4 km west and 3 km south. The straight-line distance is √(4²+3²)=5 km.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-059","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":59,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A cube has all its faces painted with different colours. It is cut into smaller cubes of equal sizes such that the side of the small cube is one-fourth the big cube. The number of small cubes with only one of the sides painted is:","options":{"a":"32","b":"24","c":"16","d":"8"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A cube has all its faces painted with different colours. It is cut into smaller cubes of equal sizes such that the side of the small cube is one-fourth the big cube. The number of small cubes with only one of the sides painted is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"There are four small cubes along each edge. On each face, the (4−2)²=4 interior face cubes have only one painted side. Six faces give 6×4=24.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-060","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":60,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"Ram and Shyam work on a job together for four days and complete 60% of it. Ram takes leave then and Shyam works for eight more days to complete the job. How long would Ram take to complete the entire job alone?","options":{"a":"6 days","b":"8 days","c":"10 days","d":"11 days"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Ram and Shyam work on a job together for four days and complete 60% of it. Ram takes leave then and Shyam works for eight more days to complete the job. How long would Ram take to complete the entire job alone?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Together their daily rate is 60 percent/4 = 15 percent. Shyam’s rate is the remaining 40 percent/8 = 5 percent. Ram’s rate is 10 percent, so he takes 10 days alone.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-061","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":61,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"A military code writes SYSTEM as SYSMET and NEARER as AENRER. Using the same code, FRACTION can be written as:","options":{"a":"CARFTION","b":"FRACNOIT","c":"NOITCARF","d":"CARFNOIT"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A military code writes SYSTEM as SYSMET and NEARER as AENRER. Using the same code, FRACTION can be written as:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The code reverses each half independently. FRACTION splits into FRAC and TION, becoming CARF and NOIT. The result is CARFNOIT.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-062","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":62,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"If R and S are different integers both divisible by 5, then which of the following is not necessarily true?","options":{"a":"R - S is divisible by 5","b":"R + S is divisible by 10","c":"R x S is divisible by 25","d":"R² + S² is divisible by 5"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"If R and S are different integers both divisible by 5, then which of the following is not necessarily true?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"R=5r and S=5s ensure the difference and squares are divisible by 5 and the product by 25. Their sum need not be divisible by 10: 5+10=15 is a counterexample.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-063","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":63,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"How many numbers are there between 100 and 300 which either begin with or end with 2?","options":{"a":"110","b":"111","c":"112","d":"None of the above"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"How many numbers are there between 100 and 300 which either begin with or end with 2?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"There are 100 numbers from 200 to 299, and 20 numbers ending in 2 from 102 to 292. Ten occur in both groups. Total = 100+20−10 = 110.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-064","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":64,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is the critical message conveyed by the above passage?","options":{"a":"Our increasing demand for foods sourced from animals puts a greater burden on our natural resources","b":"Diets based on grains, nuts, fruits and vegetables are best suited for health in developing countries","c":"Human beings change their food habits from time to time irrespective of the health concerns","d":"From a global perspective, we still do not know which type of diet is best for us"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"As we look to 2050, when we will need to feed two billion more people, the question of which diet is best has taken on new urgency. The foods we choose to eat in the coming decades will have dramatic ramifications for the planet. Simply put, a diet that revolves around meat and dairy a way of eating that is on the rise throughout the developing. world, will take a greater toll on the world's resources than one that revolves around unrefined grains, nuts, fruits and vegetables."},{"type":"paragraph","text":"What is the critical message conveyed by the above passage?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage contrasts the resource demands of meat and dairy with plant-based foods. Increasing demand for animal-sourced foods places greater pressure on natural resources.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-065","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":65,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most logical assumption that can be made from the above passage?","options":{"a":"About 10,000 years ago, the domestication of animals took place in some parts of the world","b":"A permanent change in the food habits of a community can bring about a genetic change in its members","c":"Lactose tolerant people only are capable of getting simple sugars in their bodies","d":"People who are not lactose tolerant cannot digest any dairy product"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"All humans digest mother's milk as infants, but until cattle began being domesticated 10,000 years ago, children once weaned no longer needed to digest milk. As a result, they stopped making the enzyme lactase, which breaks down the sugar lactose into simple sugars. After humans began herding cattle, it became tremendously advantageous to digest milk, and lactose tolerance evolved independently among cattle herders in Europe, the middle East and Africa. Groups not dependant on cattle, such as the Chinese and Thai, remain lactose intolerant."},{"type":"paragraph","text":"Which among the following is the most logical assumption that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage connects long-term milk consumption among cattle herders with the evolution of lactose tolerance. It supports the assumption that sustained dietary habits can accompany genetic change in a community.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-066","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":66,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"In the above statement, the author implies that:","options":{"a":"the entire national output produced and consumed in industrialized countries passes through commercial channels","b":"the existence of a non-commercialized sector in different underdeveloped countries renders the national income comparisons over countries difficult","c":"no part of national output should be produced and consumed without passing through commercial channels","d":"a part of the national output being produced and consumed without passing through commercial channels is a sign of underdevelopment"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"\\"The conceptual difficulties in National Income comparisons between underdeveloped and industrialised countries are particularly serious because a part of the national output in various underdeveloped countries is produced without passing through the commercial channels.\\""},{"type":"paragraph","text":"In the above statement, the author implies that:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Unrecorded, non-commercial production makes cross-country national-income comparisons conceptually difficult. The passage does not claim all industrial-country output is commercial.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-067","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":67,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most logical corollary to the above passage ?","options":{"a":"Carbon dioxide is essential for the survival of microorganisms and plants","b":"Humans are solely responsible for the release of carbon dioxide into the atmosphere","c":"Microorganisms and soil carbon are mainly responsible for the increased plant growth","d":"Increasing green cover could trigger the release of carbon trapped in soil"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"An increase in human-made carbon dioxide in the atmosphere could initiate a chain reaction between plants and microorganisms that would unsettle one of the largest carbon reservoirs on the planet — soil. In a study, it was found that the soil, which contains twice the amount of carbon present in all plants and Earth’s atmosphere combined, could become increasingly volatile as people add more carbon dioxide to the atmosphere. This is largely because of increased plant growth. Although a greenhouse gas and a pollutant, carbon dioxide also supports plant growth. As trees and other vegetation flourish in a carbon dioxide-rich future, their roots could stimulate microbial activity in soil that may in turn accelerate the decomposition of soil carbon and its release into the atmosphere as carbon dioxide."},{"type":"paragraph","text":"Which among the following is the most logical corollary to the above passage ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Additional carbon dioxide can stimulate plants, whose roots stimulate microbes and accelerate decomposition of soil carbon. Thus increasing vegetation can trigger release of stored soil carbon under the described conditions.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-068","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":68,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"According to the above passage, which of, the following are the fundamental solutions for the world food security problem?\\n\\n1. Setting up more agro-based industries\\n\\n2. Improving the price affordability by the poor\\n\\n3. Regulating the conditions of marketing\\n\\n4. Providing food subsidy to one and all\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"2 and 3 only","c":"1, 3 and 4 only","d":"1, 2, 3 and 4"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Historically, the biggest challenge to world agriculture has been to achieve a balance between demand for and supply of food. At the level of individual countries, the demand-supply balance can be a critical policy issue for a closed economy, especially if it is a populous economy and its domestic agriculture is not growing sufficiently enough to ensure food supplies, on an enduring basis; it is not so much and not always, of a constraint for an open, and growing economy, which has adequate exchange surpluses to buy food abroad. For the world as a whole, supply-demand balance is always an inescapable prerequisite for warding off hunger and starvation. However, global availability of adequate supply does not necessarily mean that food would automatically move from countries of surplus to countries of deficit if the latter lack in purchasing power. The uneven distribution of hunger, starvation, under- or malnourishment, etc., at the world-level, thus owes itself to the presence of empty-pocket hungry mouths, overwhelmingly confined to the underdeveloped economies. Inasmuch as ‘a two-square meal’ is of elemental significance to basic human existence, the issue of worldwide supply of food has been gaining significance, in recent times, both because the quantum and the composition of demand has been undergoing big changes, and because, in recent years, the capabilities of individual countries to generate uninterrupted chain of food supplies have come under strain. Food production, marketing and prices, especially price-affordability by the poor in the developing world, have become global issues that need global thinking and global solutions."},{"type":"paragraph","text":"According to the above passage, which of, the following are the fundamental solutions for the world food security problem?"},{"type":"paragraph","text":"1. Setting up more agro-based industries"},{"type":"paragraph","text":"2. Improving the price affordability by the poor"},{"type":"paragraph","text":"3. Regulating the conditions of marketing"},{"type":"paragraph","text":"4. Providing food subsidy to one and all"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage stresses affordable prices for poor people and food marketing as global issues. It does not prescribe universal subsidies or more agro-industries as fundamental solutions. Thus 2 and 3 only.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-069","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":69,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"According to the above passage, the biggest challenge to world agriculture is:","options":{"a":"to find sufficient land for agriculture and to expand food processing industries","b":"to eradicate hunger in underdeveloped countries","c":"to achieve a balance between the production of food and non-food items","d":"to achieve a balance between demand for and supply of food"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Historically, the biggest challenge to world agriculture has been to achieve a balance between demand for and supply of food. At the level of individual countries, the demand-supply balance can be a critical policy issue for a closed economy, especially if it is a populous economy and its domestic agriculture is not growing sufficiently enough to ensure food supplies, on an enduring basis; it is not so much and not always, of a constraint for an open, and growing economy, which has adequate exchange surpluses to buy food abroad. For the world as a whole, supply-demand balance is always an inescapable prerequisite for warding off hunger and starvation. However, global availability of adequate supply does not necessarily mean that food would automatically move from countries of surplus to countries of deficit if the latter lack in purchasing power. The uneven distribution of hunger, starvation, under- or malnourishment, etc., at the world-level, thus owes itself to the presence of empty-pocket hungry mouths, overwhelmingly confined to the underdeveloped economies. Inasmuch as ‘a two-square meal’ is of elemental significance to basic human existence, the issue of worldwide supply of food has been gaining significance, in recent times, both because the quantum and the composition of demand has been undergoing big changes, and because, in recent years, the capabilities of individual countries to generate uninterrupted chain of food supplies have come under strain. Food production, marketing and prices, especially price-affordability by the poor in the developing world, have become global issues that need global thinking and global solutions."},{"type":"paragraph","text":"According to the above passage, the biggest challenge to world agriculture is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The opening sentence identifies the historic challenge as balancing food demand and supply. That is the direct answer.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-070","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":70,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"According to the above passage, which of the following helps/help in reducing hunger and starvation in the developing economies ?\\n\\n1. Balancing demand and supply of food\\n\\n2. Increasing imports of food\\n\\n3. Increasing purchasing power of the poor\\n\\n4. Changing the food consumption patterns and practices\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"2, 3 and 4 only","c":"1 and 3 only","d":"1, 2, 3 and 4"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Historically, the biggest challenge to world agriculture has been to achieve a balance between demand for and supply of food. At the level of individual countries, the demand-supply balance can be a critical policy issue for a closed economy, especially if it is a populous economy and its domestic agriculture is not growing sufficiently enough to ensure food supplies, on an enduring basis; it is not so much and not always, of a constraint for an open, and growing economy, which has adequate exchange surpluses to buy food abroad. For the world as a whole, supply-demand balance is always an inescapable prerequisite for warding off hunger and starvation. However, global availability of adequate supply does not necessarily mean that food would automatically move from countries of surplus to countries of deficit if the latter lack in purchasing power. The uneven distribution of hunger, starvation, under- or malnourishment, etc., at the world-level, thus owes itself to the presence of empty-pocket hungry mouths, overwhelmingly confined to the underdeveloped economies. Inasmuch as ‘a two-square meal’ is of elemental significance to basic human existence, the issue of worldwide supply of food has been gaining significance, in recent times, both because the quantum and the composition of demand has been undergoing big changes, and because, in recent years, the capabilities of individual countries to generate uninterrupted chain of food supplies have come under strain. Food production, marketing and prices, especially price-affordability by the poor in the developing world, have become global issues that need global thinking and global solutions."},{"type":"paragraph","text":"According to the above passage, which of the following helps/help in reducing hunger and starvation in the developing economies ?"},{"type":"paragraph","text":"1. Balancing demand and supply of food"},{"type":"paragraph","text":"2. Increasing imports of food"},{"type":"paragraph","text":"3. Increasing purchasing power of the poor"},{"type":"paragraph","text":"4. Changing the food consumption patterns and practices"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"A sufficient demand–supply balance is necessary, but poor people also need purchasing power to access food. Both 1 and 3 are supported; the other proposals are not established as general solutions.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-071","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":71,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The issue of worldwide supply of food has gained importance mainly because of:\\n\\n1. overgrowth of the population worldwide\\n\\n2. sharp decline in the area of food production\\n\\n3. limitation in the capabilities for sustained supply of food\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Historically, the biggest challenge to world agriculture has been to achieve a balance between demand for and supply of food. At the level of individual countries, the demand-supply balance can be a critical policy issue for a closed economy, especially if it is a populous economy and its domestic agriculture is not growing sufficiently enough to ensure food supplies, on an enduring basis; it is not so much and not always, of a constraint for an open, and growing economy, which has adequate exchange surpluses to buy food abroad. For the world as a whole, supply-demand balance is always an inescapable prerequisite for warding off hunger and starvation. However, global availability of adequate supply does not necessarily mean that food would automatically move from countries of surplus to countries of deficit if the latter lack in purchasing power. The uneven distribution of hunger, starvation, under- or malnourishment, etc., at the world-level, thus owes itself to the presence of empty-pocket hungry mouths, overwhelmingly confined to the underdeveloped economies. Inasmuch as ‘a two-square meal’ is of elemental significance to basic human existence, the issue of worldwide supply of food has been gaining significance, in recent times, both because the quantum and the composition of demand has been undergoing big changes, and because, in recent years, the capabilities of individual countries to generate uninterrupted chain of food supplies have come under strain. Food production, marketing and prices, especially price-affordability by the poor in the developing world, have become global issues that need global thinking and global solutions."},{"type":"paragraph","text":"The issue of worldwide supply of food has gained importance mainly because of:"},{"type":"paragraph","text":"1. overgrowth of the population worldwide"},{"type":"paragraph","text":"2. sharp decline in the area of food production"},{"type":"paragraph","text":"3. limitation in the capabilities for sustained supply of food"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage states that countries’ ability to sustain uninterrupted food supply has come under strain. It does not state a sharp loss of production area or attribute the issue specifically to population overgrowth. Thus 3 only.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-072","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":72,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Four-digit numbers are to be formed using the digits 1, 2, 3 and 4; and none of these four digits are repeated in any manner. Further,\\n\\n1. 2 and 3 are not to immediately follow each other\\n\\n2. 1 is not to be immediately followed by 3\\n\\n3. 4 is not to appear at the last place\\n\\n4. 1 is not to appear at the first place\\n\\nHow many different numbers can be formed?","options":{"a":"6","b":"8","c":"9","d":"None of the above"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Four-digit numbers are to be formed using the digits 1, 2, 3 and 4; and none of these four digits are repeated in any manner. Further,"},{"type":"paragraph","text":"1. 2 and 3 are not to immediately follow each other"},{"type":"paragraph","text":"2. 1 is not to be immediately followed by 3"},{"type":"paragraph","text":"3. 4 is not to appear at the last place"},{"type":"paragraph","text":"4. 1 is not to appear at the first place"},{"type":"paragraph","text":"How many different numbers can be formed?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The admissible numbers are 2143, 2431, 3142, 3412, 3421 and 4312. Each avoids adjacent 2–3 in either order, avoids 1 immediately followed by 3, starts without 1 and ends without 4. There are six.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-073","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":73,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A cylindrical overhead tank of radius 2 m and height 7 m is to be filled from an underground tank of size 5.5m x 4m x 6m. How much portion of the underground tank is still filled with water after filling the overhead tank completely?","options":{"a":"1/3","b":"1/2","c":"1/4","d":"1/6"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A cylindrical overhead tank of radius 2 m and height 7 m is to be filled from an underground tank of size 5.5m x 4m x 6m. How much portion of the underground tank is still filled with water after filling the overhead tank completely?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Using π=22/7, the cylinder holds π×2²×7=88 m³. The underground tank holds 5.5×4×6=132 m³, leaving 44 m³, or one-third.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-074","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":74,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"In a class of 60 students, where the number of girls is twice that of boys, Kamal, a boy, ranked seventeenth from the top. If there are 9 girls ahead of Kamal, the number of boys in rank after him is:","options":{"a":"13","b":"12","c":"7","d":"3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In a class of 60 students, where the number of girls is twice that of boys, Kamal, a boy, ranked seventeenth from the top. If there are 9 girls ahead of Kamal, the number of boys in rank after him is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"There are 20 boys and 40 girls. Sixteen people are ahead of Kamal; nine are girls, so seven are boys. Including Kamal, eight boys are at or above him, leaving 20−8=12 below.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-075","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":75,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A and B walk around a circular park. They start at 8 a.m. from the same point in the opposite directions. A and B walk at a speed of 2 rounds per hour and 3 rounds per hour respectively. How many times shall they cross each other after 8 00 a.m. and before 9.30. a.m.?","options":{"a":"7","b":"6","c":"5","d":"8"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A and B walk around a circular park. They start at 8 a.m. from the same point in the opposite directions. A and B walk at a speed of 2 rounds per hour and 3 rounds per hour respectively. How many times shall they cross each other after 8 00 a.m. and before 9.30. a.m.?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Their relative speed is 2+3=5 rounds per hour, so they cross every 12 minutes. The crossings strictly before 9:30 a.m. occur at 12, 24, 36, 48, 60, 72 and 84 minutes: seven.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-076","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":76,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"W can do 25% of a work-in 30 days, X can do 1/4 of the work in 10 days, Y can do 40% of the work in 40 days and Z can do 1/3 of the work in 13 days. Who will complete the work first?","options":{"a":"W","b":"X","c":"Y","d":"Z"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"W can do 25% of a work-in 30 days, X can do 1/4 of the work in 10 days, Y can do 40% of the work in 40 days and Z can do 1/3 of the work in 13 days. Who will complete the work first?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Their full-work times are W=120 days, X=40 days, Y=100 days and Z=39 days. Z completes the work first.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-077","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":77,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"The average monthly income of a person in a certain family of 5 is Rs. 10,000. What will be the average monthly income of a person in the same family if the income of one person increased by Rs. 1,20,000 per year?","options":{"a":"Rs. 12,000","b":"Rs. 16,000","c":"Rs. 20,000","d":"Rs. 34,000"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"The average monthly income of a person in a certain family of 5 is Rs. 10,000. What will be the average monthly income of a person in the same family if the income of one person increased by Rs. 1,20,000 per year?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The family’s original monthly total is 5×10,000=50,000 rupees. The annual increase of 120,000 adds 10,000 per month. The new average is 60,000/5=12,000 rupees.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-078","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":78,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"In a race, a competitor has to collect 6 apples which are kept in a straight line On a track and a bucket is placed at the beginning of the track which is a starting point. The condition is that the competitor can pick only one apple at a time, run back with it and drop it in the bucket. If he has to drop all the apples in the bucket, how much total distance he has to run if the bucket is 5 meters from the first apple and all other apples are placed 3 meters apart ?","options":{"a":"40 m","b":"50 m","c":"75 m","d":"150 m"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In a race, a competitor has to collect 6 apples which are kept in a straight line On a track and a bucket is placed at the beginning of the track which is a starting point. The condition is that the competitor can pick only one apple at a time, run back with it and drop it in the bucket. If he has to drop all the apples in the bucket, how much total distance he has to run if the bucket is 5 meters from the first apple and all other apples are placed 3 meters apart ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The apples are 5, 8, 11, 14, 17 and 20 m from the bucket. Each collection requires an outward and return trip. Total distance = 2×(5+8+11+14+17+20)=150 m, which is option D in the original paper.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-079","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":79,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A round archery target of diameter 1 m is marked with four scoring regions from the centre outwards as red, blue, yellow and white. The radius of the red band is 0.20 m. The width of all the remaining bands is equal. If archers throw arrows towards the target, what is the probability, that the arrows fall in the red region of the archery target?","options":{"a":"0.40","b":"0.20","c":"0.16","d":"0.04"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A round archery target of diameter 1 m is marked with four scoring regions from the centre outwards as red, blue, yellow and white. The radius of the red band is 0.20 m. The width of all the remaining bands is equal. If archers throw arrows towards the target, what is the probability, that the arrows fall in the red region of the archery target?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Assuming equal chance per unit area, the probability is the red disk’s area divided by total area: (0.20/0.50)² = 0.16.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-080","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":80,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A person allows 10% discount for cash payment from the marked price of a toy and still he makes a 10% gain. What is the cost price of the toy which is marked Rs. 770?","options":{"a":"Rs. 610","b":"Rs. 620","c":"Rs. 630","d":"Rs. 640"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A person allows 10% discount for cash payment from the marked price of a toy and still he makes a 10% gain. What is the cost price of the toy which is marked Rs. 770?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The selling price after discount is 770×0.90=693 rupees. This is 110 percent of cost, so cost = 693/1.10 = 630 rupees.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}}]`);export{e as p};
